/* From Uiverse.io by Uncannypotato69  - Tags: simple, animation, loading, loader, text, css, loading animation */
.__UIV_SCOPE__ .wrapper {
  min-height: 3rem;
  min-width: 14rem;
  font-size: 2rem;
  position: relative;
  overflow: hidden;
  mask-image: linear-gradient(
    to right,
    rgba(0, 0, 0, 0),
    rgba(0, 0, 0, 1) 30%,
    rgba(0, 0, 0, 1) 70%,
    rgba(0, 0, 0, 0)
  );
  font-family: monospace;
}

.__UIV_SCOPE__ .letter {
  width: 1ch;
  position: absolute;
  top: 50%;
  transform: translate(0px, -50%);
  left: 100%;
  animation: scroll 2.5s linear infinite;
}

@keyframes scroll {
  to {
    left: -1ch;
  }
}

.__UIV_SCOPE__ .letter1 {
  animation-delay: calc(2.5s / 10 * (10 - 1) * -1);
}
.__UIV_SCOPE__ .letter2 {
  animation-delay: calc(2.5s / 10 * (10 - 2) * -1);
}
.__UIV_SCOPE__ .letter3 {
  animation-delay: calc(2.5s / 10 * (10 - 3) * -1);
}
.__UIV_SCOPE__ .letter4 {
